#import "TVAppleServices.h"
#include <string.h>
int main(void){@autoreleasepool{TVAppleServices *s=[TVAppleServices new];char line[4096];while(fgets(line,sizeof(line),stdin)){id c=[NSJSONSerialization JSONObjectWithData:[NSData dataWithBytes:line length:strlen(line)]options:0 error:NULL];memset(line,0,sizeof(line));if(![c isKindOfClass:NSDictionary.class]||![c[@"apple_id"]isKindOfClass:NSString.class])return 2;__block BOOL done=NO;TVAppleCompletion reply=^(NSDictionary *r,NSError *e){NSMutableDictionary *out=[r mutableCopy]?:[NSMutableDictionary new];if(e){out[@"error_code"]=@(e.code);out[@"error"]=e.localizedDescription;}NSData *j=[NSJSONSerialization dataWithJSONObject:out options:0 error:NULL];puts([[NSString alloc]initWithData:j encoding:NSUTF8StringEncoding].UTF8String);fflush(stdout);@synchronized(s){done=YES;}};if([c[@"action"]isEqual:@"query"])[s queryICloudDevices:c[@"apple_id"]completion:reply];else if([c[@"action"]isEqual:@"remove_others"])[s removeOtherICloudDevices:c[@"apple_id"]completion:reply];else return 2;c=nil;NSTimeInterval deadline=NSProcessInfo.processInfo.systemUptime+3600;for(;;){@synchronized(s){if(done)break;}if(NSProcessInfo.processInfo.systemUptime>=deadline)return 3;[[NSRunLoop currentRunLoop]runUntilDate:[NSDate dateWithTimeIntervalSinceNow:.02]];}}return 0;}}
